      '\u062f \u062f\u0646\u062f\u0648 \u0627\u0648 \u0631\u0648\u0644\u0648\u0646\u0648 \u0645\u062f\u06cc\u0631\u06cc\u062a',
  'Task permissions':
      '\u062f \u062f\u0646\u062f\u0648 \u0635\u0644\u0627\u062d\u06cc\u062a\u0648\u0646\u0647',
  'Application tasks':
      '\u062f \u067e\u0631\u0648\u06ab\u0631\u0627\u0645 \u062f\u0646\u062f\u06d0',
  'Changes saved.':
      '\u0628\u062f\u0644\u0648\u0646\u0648\u0646\u0647 \u062e\u0648\u0646\u062f\u064a \u0634\u0648\u0644.',
  'Add task': '\u062f\u0646\u062f\u0647 \u0632\u06cc\u0627\u062a\u0648\u0644',
  'Edit task': '\u062f\u0646\u062f\u0647 \u0633\u0645\u0648\u0644',
  'Add role': '\u0631\u0648\u0644 \u0632\u06cc\u0627\u062a\u0648\u0644',
  'Edit role': '\u0631\u0648\u0644 \u0633\u0645\u0648\u0644',
  'Task key': '\u062f \u062f\u0646\u062f\u06d0 \u06a9\u0644\u06cc\u062f',
  'Built-in role':
      '\u062f \u067e\u0631\u0648\u06ab\u0631\u0627\u0645 \u0627\u0635\u0644\u064a \u0631\u0648\u0644',
  'Custom role': '\u0681\u0627\u0646\u06ab\u0693\u06cc \u0631\u0648\u0644',
  'Remove permission record':
      '\u062f \u0635\u0644\u0627\u062d\u06cc\u062a \u062b\u0628\u062a \u0644\u0631\u06d0 \u06a9\u0648\u0644',
  'Enter a valid name.':
      '\u0633\u0645 \u0646\u0648\u0645 \u0648\u0644\u06cc\u06a9\u0626.',
  'Use letters, numbers, and dots; start with a letter.':
      '\u062a\u0648\u0631\u064a\u060c \u0634\u0645\u06d0\u0631\u06d0 \u0627\u0648 \u067c\u06a9\u064a \u0648\u06a9\u0627\u0631\u0648\u0626\u061b \u067e\u0647 \u062a\u0648\u0631\u064a \u06cc\u06d0 \u067e\u06cc\u0644 \u06a9\u0693\u0626.',
  'Delete this custom role and its permission records?':
      '\u062f\u0627 \u0681\u0627\u0646\u06ab\u0693\u06cc \u0631\u0648\u0644 \u0627\u0648 \u062f \u0635\u0644\u0627\u062d\u06cc\u062a \u062b\u0628\u062a\u0648\u0646\u0647 \u06cc\u06d0 \u0693\u0646\u06ab \u0634\u064a\u061f',
  'Delete this custom task? Remove its role permission records first.':
      '\u062f\u0627 \u0681\u0627\u0646\u06ab\u0693\u06d0 \u062f\u0646\u062f\u0647 \u0693\u0646\u06ab\u0647 \u0634\u064a\u061f \u0644\u0648\u0645\u0693\u06cc \u062f \u0631\u0648\u0644\u0648\u0646\u0648 \u062f \u0635\u0644\u0627\u062d\u06cc\u062a \u062b\u0628\u062a\u0648\u0646\u0647 \u06cc\u06d0 \u0644\u0631\u06d0 \u06a9\u0693\u0626.',
  'Task grants also require the matching component permission. Missing grants deny access.':
      '\u062f \u062f\u0646\u062f\u06d0 \u0635\u0644\u0627\u062d\u06cc\u062a \u062f \u0627\u0693\u0648\u0646\u062f\u06d0 \u0628\u0631\u062e\u06d0 \u0635\u0644\u0627\u062d\u06cc\u062a \u062a\u0647 \u0647\u0645 \u0627\u0693\u062a\u06cc\u0627 \u0644\u0631\u064a. \u062f \u0635\u0644\u0627\u062d\u06cc\u062a \u0646\u0634\u062a\u0648\u0627\u0644\u06cc \u0644\u0627\u0633\u0631\u0633\u06cc \u0628\u0646\u062f\u0648\u064a.',
  'Task keys identify application operations. New tasks require code integration before they protect an action.':
      '\u062f \u062f\u0646\u062f\u0648 \u06a9\u0644\u06cc\u062f\u0648\u0646\u0647 \u062f \u067e\u0631\u0648\u06ab\u0631\u0627\u0645 \u0639\u0645\u0644\u06cc\u0627\u062a \u067c\u0627\u06a9\u064a. \u0646\u0648\u06d0 \u062f\u0646\u062f\u06d0 \u062f \u06cc\u0648\u0647 \u0639\u0645\u0644 \u0644\u0647 \u06a9\u0646\u067c\u0631\u0648\u0644 \u0645\u062e\u06a9\u06d0 \u067e\u0647 \u067e\u0631\u0648\u06ab\u0631\u0627\u0645 \u06a9\u06d0 \u067e\u0644\u064a \u06a9\u0648\u0644\u0648 \u062a\u0647 \u0627\u0693\u062a\u06cc\u0627 \u0644\u0631\u064a.',
  'Built-in roles are protected. New roles start without component or task grants.':
      '\u0627\u0635\u0644\u064a \u0631\u0648\u0644\u0648\u0646\u0647 \u062e\u0648\u0646\u062f\u064a \u062f\u064a. \u0646\u0648\u064a \u0631\u0648\u0644\u0648\u0646\u0647 \u062f \u0628\u0631\u062e\u0648 \u0627\u0648 \u062f\u0646\u062f\u0648 \u0644\u0647 \u0635\u0644\u0627\u062d\u06cc\u062a\u0648\u0646\u0648 \u067e\u0631\u062a\u0647 \u062c\u0648\u0693\u06d0\u0696\u064a.',
};
